{
  "status": "SUPPORTED",
  "task_summary": "Identify components, fasten assembly, place tool on workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "assembly_target",
        "entity_kind": "OBJECT",
        "function": "The object on the workbench that requires fastening.",
        "required_count": 1
      ,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["mechanism", "assembly", "device"],
        "required_properties": ["has_fastening_points", "is_on_workbench"]
      },
      {
        "id": "component_part",
        "entity_kind": "OBJECT",
        "function": "Parts required to complete the assembly.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["part", "piece", "component"],
        "required_properties": ["compatible_with_assembly_target", "suitable_for_fastening"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "Tool used to secure the components.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screwdriver", "wrench", "tool"],
        "required_properties": ["can_apply_fastening_force", "portable"]
      },
      {
        "id": "storage_unit",
        "entity_kind": "REGION",
        "function": "Containers where components or tools may be stored.",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["cabinet", "drawer", "storage_box"],
        "required_properties": ["has_openable_door_or_drawer", "located_near_workbench"]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "Surface where the assembly is located and tool is placed.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk", "surface"],
        "required_properties": ["supports_objects", "flat_surface"]
      },
      {
        "id": "robot_arm",
        "entity_kind": "OBJECT",
        "function": "The agent performing the task.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["manipulator", "arm", "robot"],
        "required_properties": ["can_grasp", "can_move"]
      }
    ],
    "functional_relations": [
      {
        "id": "needs_component",
        "relation": "The assembly target requires a component part to be completed.",
        "participant_roles": ["assembly_target", "component_part"]
      ,
        "required": true
      },
      {
        "id": "operates_on",
        "relation": "The robot arm uses the fastening tool to act on the assembly target and component part.",
        "participant_roles": ["robot_arm", "fastening_tool", "assembly_target", "component_part"]
      ,
        "required": true
      },
      {
        "id": "rests_on",
        "relation": "The fastening tool is placed on the workbench.",
        "participant_roles": ["fastening_tool", "workbench"]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "locate_component",
        "operation": "Search storage units to find the component part.",
        "participant_roles": ["robot_arm", "storage_unit", "component_part"],
        "operation_count": 1
      },
      {
        "id": "fasten",
        "operation": "Use the fastening tool to attach the component to the assembly.",
        "participant_roles": ["robot_arm", "fastening_tool", "assembly_target", "component_part"],
        "operation_count": 1
      },
      {
        "id": "place_tool",
        "operation": "Move the fastening tool to the workbench.",
        "participant_roles": ["robot_arm", "fastening_tool", "workbench"],
        "operation_count": 1
      }
    ]
  },
